/* @lc app=leetcode id=3928 lang=kotlin */ class Solution { fun dj(n: Int, g: Map<Int, List<Pair<Int, Long>>>, s: Int): LongArray = LongArray(n) { Long.MAX_VALUE / 4 }.also { it[s] = 0L }.let { d -> java.util.PriorityQueue<Pair<Long, Int>>(compareBy<Pair<Long, Int>> { it.first }).also { it.add(0L to s) }.let { pq -> generateSequence { pq.poll() }.filter { (c, u) -> c == d[u] }.forEach { (c, u) -> g[u].orEmpty().filter { (v, w) -> c + w < d[v] }.forEach { (v, w) -> pq.add(c + w to v).also { d[v] = c + w } } }.let { d } } } fun minCost(n: Int, prices: IntArray, roads: Array<IntArray>): IntArray = roads.flatMap { (a, b, c, _) -> listOf(a to (b to c.toLong()), b to (a to c.toLong())) }.groupBy({ it.first }, { it.second }).let { g1 -> roads.flatMap { (a, b, c, t) -> listOf(a to (b to c.toLong() * t), b to (a to c.toLong() * t)) }.groupBy({ it.first }, { it.second }).let { g2 -> IntArray(n) { i -> dj(n, g1, i).let { de -> dj(n, g2, i).let { dt -> (0 until n).minOf { j -> if (de[j] >= Long.MAX_VALUE / 8 || dt[j] >= Long.MAX_VALUE / 8) Long.MAX_VALUE / 4 else de[j] + dt[j] + prices[j] }.toInt() } } } } } }